import React, { useEffect } from 'react';
import { Layout as LayoutAntd } from 'antd';
import styled from 'styled-components';
import HeaderMenu from './HeaderMenu';
import { Link } from 'gatsby';
import Halmet from 'react-helmet';
import favicon from '../images/favicon.ico';
import { startPresence } from './presence.mjs';

import 'antd/dist/antd.css';
import './tokens.css';
import './layout.css';

const BREAK_POINT = 768;

const {
  Header: HeaderAntd,
  Sider: SiderAntd,
  Content: ContentAntd,
} = LayoutAntd;

function Header({ current }) {
  return (
    <HeaderAntd>
      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
        <Link className='page-title' to='/' style={{ color: 'inherit' }}>
          <h1 className='page-title-text' 
            style={{ marginBottom: 0, fontSize: 'var(--dara-font-16)', fontWeight: 600, lineHeight: '48px' }}
          >
            DARA
          </h1>
        </Link>
        <HeaderMenu current={current}></HeaderMenu>
      </div>
    </HeaderAntd>
  )
}

function Sider() {
  return (<></>)
}

/** A render error shows the header, one line and a way back instead of a white page. */
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error) { console.error(error); }
  render() {
    if (!this.state.error) return this.props.children;
    return <div role="alert" className="dara-empty">
      <h3>This page could not be displayed</h3>
      <p>{String(this.state.error?.message || this.state.error).split('\n')[0]}</p>
      <Link to="/results/">Back to Results</Link>
    </div>;
  }
}

const LayoutContainer = styled(LayoutAntd)`
  background: var(--dara-surface);
  min-height: 100vh;

  .ant-layout-header {
    padding: 0 clamp(16px, 2vw, 48px);
    margin-bottom: 8px;
    height: 48px;
    line-height: 48px;
    border-bottom: 1px solid var(--dara-border);
  }

  .ant-layout-header .ant-menu-horizontal {
    line-height: 46px;
  }

  .page-title-text {
    transition: all 0.2s;
  }

  .page-title-text:hover {
    color: rgba(0, 0, 0, 0.5);
  }

  .ant-layout-header,
  .ant-layout-footer {
    background: var(--dara-surface);
  }

  .ant-layout-sider {
    padding: 16px 24px;
  }

  .ant-layout-content {
    padding: 16px clamp(16px, 2vw, 48px);
    min-width: 0;
  }

  .ant-layout-sider {
    transition: none;
  }

  .ant-divider-horizontal {
    margin: 8px 0;
  }

  .ant-menu-title-content {
    font-weight: 500;
  }

  .sider-container {
    display: block;
  }

  .sider-container-collapsed {
    display: none;
  }

  @media (max-width: ${BREAK_POINT}px) {
    .main-container {
      flex-direction: column !important;
    }

    .ant-layout-sider,
    .ant-layout-content {
      padding: 4px 32px;
    }

    .ant-layout-sider {
      width: 100% !important;
      max-width: 100% !important;
      min-width: 100% !important;
      flex: unset !important;
    }

    .main-container > .ant-layout-content {
      width: 100% !important;
    }

    .sider-container {
      display: none !important;
    }
  
    .sider-container-collapsed {
      display: block !important;
    }
  }

  @media (max-width: 568px) {
    .page-title {
      display: none;
    }
  }
`;

const ContentContainer = styled(LayoutAntd)`
  background: var(--dara-surface);
  flex: 1 0 auto;
  width: 100%;
  max-width: 1920px;
  margin: 0 auto;
`;

function Layout({ children, hasSider, title }) {
  useEffect(() => { startPresence(); }, []);
  return (
      <LayoutContainer className="layout-container">
        <Halmet>
          <title>{title ? `${title} | `: ""}DARA | Data-driven automated Rietveld analysis for phase search and refinement</title>
        </Halmet>
        <Halmet>
          <link rel="icon" href={favicon} />
        </Halmet>
        <Halmet>
          <meta charset="utf-8" />
        </Halmet>
        <Halmet>
          <meta http-equiv="X-UA-Compatible" content="chrome=1" />
        </Halmet>
        <Halmet>
          <meta name="keywords" content="DARA, XRD, Rietveld refinement, phase identification" />
        </Halmet>
        <Halmet>
          <meta name="subject" content="XRD phase identification and Rietveld refinement" />
        </Halmet>

        <Header></Header>
        <ContentContainer className='main-container'>
          {hasSider ? <Sider /> : null}
          <ContentAntd>
            <ErrorBoundary>{children}</ErrorBoundary>
          </ContentAntd>
        </ContentContainer>
      </LayoutContainer>
  )
}

export { BREAK_POINT };
export default Layout;